INSERT INTO public.content (page, section, key, value, type, "order") VALUES
('privacy', 'header', 'title', '{"text":"Privacy Policy"}', 'text', 0),
('privacy', 'header', 'effective_date', '{"text":"June 29, 2026"}', 'text', 0),
('privacy', 'header', 'intro', '{"text":"Eyes Closed (\"we,\" \"us,\" or \"our\") operates this website and related communications about inner awareness, the Formless book, and future offerings from Sonika Cottman. This policy explains what information we collect, how we use it, and the choices you have."}', 'text', 0),
('privacy', 'header', 'contact_email', '{"text":"hello@eyesclosed.love"}', 'text', 0),
('privacy', 'sections', 'information-we-collect', '{"id":"information-we-collect","title":"Information we collect","paragraphs":["We collect only what is needed to run the site, respond to interest in the book, and send updates you ask for."],"list":["Email address and signup source when you join the book waitlist or the Stay Close list on the About page.","Basic technical information that browsers and hosting services send automatically, such as IP address, browser type, device type, referring page, and pages visited.","Messages you send us directly by email."]}'::jsonb, 'list_item', 0),
('privacy', 'sections', 'how-we-use-information', '{"id":"how-we-use-information","title":"How we use information","paragraphs":["We use the information above to:"],"list":["Send book release updates and occasional reflections or announcements you signed up for.","Operate, secure, and improve the website.","Respond to questions or requests you send us.","Understand general site usage so we can maintain performance and fix problems."]}'::jsonb, 'list_item', 1),
('privacy', 'sections', 'how-we-share', '{"id":"how-we-share","title":"How we share information","paragraphs":["We do not sell your personal information. We share information only with service providers that help us run the site, and only as needed for them to perform their work.","Current providers may include hosting and deployment services (such as Vercel) and database services (such as Supabase) used to store email signups securely. These providers process data on our behalf under their own privacy terms.","We may also disclose information if required by law, to protect rights and safety, or in connection with a business transfer, such as a merger or acquisition."]}'::jsonb, 'list_item', 2),
('privacy', 'sections', 'email-choices', '{"id":"email-choices","title":"Email communications and your choices","paragraphs":["If you join a mailing list, we will use your email for the purpose described at signup. You can unsubscribe from marketing or update emails at any time by using the unsubscribe link in an email, if provided, or by contacting us directly.","Even if you unsubscribe from updates, we may still keep a record that you previously signed up so we do not re-add you by mistake."]}'::jsonb, 'list_item', 3),
('privacy', 'sections', 'retention', '{"id":"retention","title":"How long we keep information","paragraphs":["We keep signup information for as long as needed to send the communications you requested, maintain our records, and comply with legal obligations. When information is no longer needed, we delete it or anonymize it where practical."]}'::jsonb, 'list_item', 4),
('privacy', 'sections', 'security', '{"id":"security","title":"Security","paragraphs":["We use reasonable administrative, technical, and organizational measures to protect information. No website or email system can be guaranteed completely secure, so please use caution when sharing information online."]}'::jsonb, 'list_item', 5),
('privacy', 'sections', 'your-rights', '{"id":"your-rights","title":"Your rights and requests","paragraphs":["Depending on where you live, you may have rights to access, correct, delete, or restrict certain uses of your personal information, or to object to processing. To make a request, email us using the contact details below. We may need to verify your request before responding."]}'::jsonb, 'list_item', 6),
('privacy', 'sections', 'children', '{"id":"children","title":"Children''s privacy","paragraphs":["This site is intended for adults. We do not knowingly collect personal information from children under 13. If you believe a child has provided us information, contact us and we will take steps to delete it."]}'::jsonb, 'list_item', 7),
('privacy', 'sections', 'international', '{"id":"international","title":"International visitors","paragraphs":["If you visit from outside the United States, your information may be processed in the United States or in other countries where our service providers operate. By using the site, you understand that your information may be transferred to locations with different data protection laws than your own."]}'::jsonb, 'list_item', 8),
('privacy', 'sections', 'changes', '{"id":"changes","title":"Changes to this policy","paragraphs":["We may update this Privacy Policy from time to time. When we do, we will revise the effective date at the top of this page. Continued use of the site after changes become effective means you accept the updated policy."]}'::jsonb, 'list_item', 9),
('privacy', 'sections', 'contact', '{"id":"contact","title":"Contact us","paragraphs":["Questions about this policy or your information can be sent to hello@eyesclosed.love."]}'::jsonb, 'list_item', 10),
('terms', 'header', 'title', '{"text":"Terms of Use"}', 'text', 0),
('terms', 'header', 'effective_date', '{"text":"June 29, 2026"}', 'text', 0),
('terms', 'header', 'intro', '{"text":"These Terms of Use (\"Terms\") govern your access to and use of the Eyes Closed website and related online materials. By using the site, you agree to these Terms. If you do not agree, please do not use the site."}', 'text', 0),
('terms', 'header', 'contact_email', '{"text":"hello@eyesclosed.love"}', 'text', 0),
('terms', 'sections', 'about-the-site', '{"id":"about-the-site","title":"About the site","paragraphs":["Eyes Closed shares teachings, writing, and information related to awareness, presence, and inner transformation, including content about the book Formless by Sonika Cottman.","We may update, change, or remove site content at any time without notice."]}'::jsonb, 'list_item', 0),
('terms', 'sections', 'not-advice', '{"id":"not-advice","title":"Educational content only","paragraphs":["Content on this site is offered for general educational and reflective purposes. It is not medical advice, mental health treatment, psychotherapy, financial advice, legal advice, or any other professional service.","Nothing on this site creates a therapist-client, doctor-patient, coaching, or other professional relationship. If you need professional support, consult a qualified provider in your area.","You are responsible for your own choices and for seeking appropriate help when needed."]}'::jsonb, 'list_item', 1),
('terms', 'sections', 'acceptable-use', '{"id":"acceptable-use","title":"Acceptable use","paragraphs":["You agree not to:"],"list":["Use the site in any way that violates law or the rights of others.","Attempt to gain unauthorized access to the site, its systems, or related accounts.","Scrape, copy, or redistribute site content at scale without permission.","Upload malware, spam, or harmful code.","Harass, impersonate, or misrepresent your affiliation with Eyes Closed or Sonika Cottman."]}'::jsonb, 'list_item', 2),
('terms', 'sections', 'intellectual-property', '{"id":"intellectual-property","title":"Intellectual property","paragraphs":["The site design, text, images, logos, graphics, audio, video, and other materials are owned by Eyes Closed, Sonika Cottman, or licensors and are protected by copyright and other intellectual property laws.","You may view and download content for personal, non-commercial use only. You may not reproduce, distribute, modify, publicly display, or create derivative works from site content without prior written permission, except where allowed by law."]}'::jsonb, 'list_item', 3),
('terms', 'sections', 'email-lists', '{"id":"email-lists","title":"Email lists and communications","paragraphs":["When you submit your email address, you confirm that the address is yours and that you agree to receive the communications described at signup.","You can unsubscribe from optional updates as described in our Privacy Policy. We may still send essential service-related messages when necessary."]}'::jsonb, 'list_item', 4),
('terms', 'sections', 'third-party-links', '{"id":"third-party-links","title":"Third-party links and services","paragraphs":["The site may link to third-party websites or services. We do not control and are not responsible for their content, policies, or practices. Your use of third-party services is at your own risk."]}'::jsonb, 'list_item', 5),
('terms', 'sections', 'disclaimer', '{"id":"disclaimer","title":"Disclaimer of warranties","paragraphs":["The site and all content are provided \"as is\" and \"as available,\" without warranties of any kind, whether express or implied, including implied warranties of merchantability, fitness for a particular purpose, and non-infringement.","We do not warrant that the site will be uninterrupted, error-free, secure, or free of harmful components."]}'::jsonb, 'list_item', 6),
('terms', 'sections', 'liability', '{"id":"liability","title":"Limitation of liability","paragraphs":["To the fullest extent permitted by law, Eyes Closed, Sonika Cottman, and related parties will not be liable for any indirect, incidental, special, consequential, or punitive damages, or for any loss of profits, data, goodwill, or other intangible losses, arising from or related to your use of the site or reliance on its content.","Our total liability for any claim arising out of these Terms or the site will not exceed the greater of one hundred U.S. dollars (USD $100) or the amount you paid us, if any, in the twelve months before the claim."]}'::jsonb, 'list_item', 7),
('terms', 'sections', 'indemnity', '{"id":"indemnity","title":"Indemnification","paragraphs":["You agree to defend, indemnify, and hold harmless Eyes Closed and Sonika Cottman from claims, damages, losses, and expenses (including reasonable legal fees) arising from your misuse of the site or violation of these Terms."]}'::jsonb, 'list_item', 8),
('terms', 'sections', 'changes', '{"id":"changes","title":"Changes to these Terms","paragraphs":["We may update these Terms from time to time. The effective date at the top of this page will show when they were last revised. Continued use of the site after changes become effective means you accept the updated Terms."]}'::jsonb, 'list_item', 9),
('terms', 'sections', 'governing-law', '{"id":"governing-law","title":"Governing law","paragraphs":["These Terms are governed by the laws of the State of Nevada, United States, without regard to conflict-of-law rules. Any dispute arising from these Terms or the site will be brought in the state or federal courts located in Nevada, unless applicable law requires otherwise."]}'::jsonb, 'list_item', 10),
('terms', 'sections', 'contact', '{"id":"contact","title":"Contact","paragraphs":["Questions about these Terms can be sent to hello@eyesclosed.love."]}'::jsonb, 'list_item', 11)
